import { useEffect, useState, Fragment } from 'react';
import { toCsv, downloadCsv } from '../lib/csv.js';
import { Link } from 'react-router-dom';
import { adminListOrders, adminUpdateOrderFulfillment, adminMarkCodCollected, adminListOrderEvents } from '../../lib/adminApi.js';
import { money } from '../../lib/format.js';
import { FULFILLMENT_STATUSES, fulfillmentStatusLabel, validateFulfillmentInput } from '../../lib/orderFulfillment.js';

const STATUS_BADGE = {
  paid: 'badge-best',
  pending: 'badge-soft',
  failed: 'badge-sale',
  cancelled: 'badge-out',
};

const FULFILLMENT_BADGE = {
  shipped: 'badge-soft',
  delivered: 'badge-best',
  cancelled: 'badge-out',
};

// Build a clean, multi-line postal address from whatever fields an order
// actually has. Works for old orders created before some fields existed —
// missing pieces are simply skipped.
function formatAddress(c = {}) {
  const name = [c.firstName, c.lastName].filter(Boolean).join(' ').trim();
  const cityLine = [c.city, c.state].filter(Boolean).join(', ');
  const cityPin = [cityLine, c.pin].filter(Boolean).join(' - ');
  return [
    name,
    c.address,
    c.apartment,
    c.landmark && `Landmark: ${c.landmark}`,
    cityPin,
    c.phone && `Phone: ${c.phone}`,
  ].filter(Boolean).join('\n');
}

// What a paid (or un-cancelled) order could not be given, written by 0039's
// settle_order_holds when the payment landed after its hold had run out.
function holdWarnings(o) {
  return Array.isArray(o?.hold_warnings) ? o.hold_warnings.filter((w) => w && typeof w === 'object') : [];
}

function holdWarningText(w) {
  if (w.kind === 'stock') {
    return `${w.label || 'An item'}: ${w.short} of the ${w.qty} ordered had run out when the payment came in.`;
  }
  const why = w.reason === 'user_limit' ? 'already used by this customer'
    : w.reason === 'exhausted' ? 'fully claimed' : 'switched off';
  return `Coupon ${w.code || ''} was ${why} by then. The discount was still given and not counted.`;
}

function hasAddress(c = {}) {
  return Boolean(c.address || c.city || c.pin);
}

const dt = (iso) => (iso ? new Date(iso).toLocaleString('en-IN') : null);

/**
 * Orders as CSV (2026-11-20: for the accounts). One row per order; the items as one
 * readable cell. Where it went (name, city, state, PIN) but no street, phone or email:
 * a spreadsheet gets passed around, and those stay in the admin. Pure.
 */
export const ORDER_CSV_COLUMNS = [
  ['Order', (o) => o.order_number],
  ['Date', (o) => (o.created_at ? new Date(o.created_at).toISOString().slice(0, 10) : '')],
  ['Payment', (o) => o.payment_status || ''],
  ['Method', (o) => o.payment_method || ''],
  ['Status', (o) => o.fulfillment_status || o.status || ''],
  ['Amount (INR)', (o) => (Number.isFinite(Number(o.amount_paise)) ? Number(o.amount_paise) / 100 : '')],
  ['Units', (o) => (Array.isArray(o.items) ? o.items.reduce((n, l) => n + (Number(l?.qty) || 0), 0) : 0)],
  ['Items', (o) => (Array.isArray(o.items) ? o.items.map((l) => `${l?.name || 'Item'}${l?.variant ? ` (${l.variant})` : ''} × ${Number(l?.qty) || 1}`).join('; ') : '')],
  ['Customer', (o) => [o.customer?.firstName, o.customer?.lastName].filter(Boolean).join(' ')],
  ['City', (o) => o.customer?.city || ''],
  ['State', (o) => o.customer?.state || ''],
  ['PIN', (o) => o.customer?.pin || ''],
];
export const ordersCsv = (orders) => toCsv(orders, ORDER_CSV_COLUMNS);

/**
 * Asking a customer for a review (round 21, 2026-11-20): a polite WhatsApp message for a
 * delivered order, pointing to their orders page where "Rate your purchase" opens the
 * product's reviews. No incentive is offered (reviews stay honest). '' without a phone.
 */
export function reviewAskText(o, site = 'https://www.soralifestyle.in') {
  const first = String(o?.customer?.firstName || '').trim().split(' ')[0];
  return `Hi${first ? ` ${first}` : ''}, this is SORA LIFESTYLE. Your order ${o?.order_number || ''} was delivered — we hope you like it! If you have a minute, a short review helps other shoppers: ${site}/account/orders (tap "Rate your purchase").`;
}
export function reviewAskHref(o) {
  const d = String(o?.customer?.phone || '').replace(/\D/g, '');
  const n = d.length === 10 ? `91${d}` : d.length === 12 && d.startsWith('91') ? d : '';
  return n ? `https://wa.me/${n}?text=${encodeURIComponent(reviewAskText(o))}` : '';
}

/**
 * Packing slip (round 22, 2026-11-20): what goes in the box — ship-to, items and qty,
 * no prices (a gift should not carry them). An unpaid COD order says how much the courier
 * collects. Pure: the component below prints it.
 */
export function packingSlip(o) {
  const items = (Array.isArray(o?.items) ? o.items : []).map((l) => ({
    name: l?.name || l?.product_id || 'Item',
    variant: l?.variant || '',
    sku: l?.sku || '',
    qty: Number(l?.qty) || 1,
  }));
  const cod = o?.payment_method === 'cod' && o?.payment_status !== 'paid';
  return {
    orderNumber: o?.order_number || '',
    date: o?.created_at ? new Date(o.created_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '',
    shipTo: formatAddress(o?.customer || {}),
    items,
    units: items.reduce((n, l) => n + l.qty, 0),
    collect: cod && Number(o?.amount_paise) > 0 ? money(Number(o.amount_paise) / 100) : '',
  };
}

function PackingSlip({ order }) {
  const s = packingSlip(order);
  return (
    <div className="adm-slip" aria-hidden="true">
      <div className="adm-slip__head">
        <strong>SORA LIFESTYLE</strong>
        <span>Packing slip</span>
      </div>
      <p className="adm-slip__meta">Order {s.orderNumber}{s.date && ` · ${s.date}`}</p>
      <h4>Ship to</h4>
      <address>{s.shipTo || 'No address on record'}</address>
      <table>
        <thead><tr><th>Item</th><th>Size / variant</th><th>Qty</th></tr></thead>
        <tbody>
          {s.items.map((l, i) => (
            <tr key={i}><td>{l.name}{l.sku && <small> · {l.sku}</small>}</td><td>{l.variant || '—'}</td><td>{l.qty}</td></tr>
          ))}
        </tbody>
      </table>
      <p className="adm-slip__meta">{s.units} {s.units === 1 ? 'item' : 'items'} in this parcel</p>
      {s.collect && <p className="adm-slip__cod">Cash on delivery: collect {s.collect}</p>}
      <p className="adm-slip__foot">Thank you for shopping with SORA LIFESTYLE · www.soralifestyle.in</p>
    </div>
  );
}

/**
 * "On its way" (round 22, 2026-11-20): a WhatsApp message for a shipped order with the
 * courier and tracking link (or the customer's orders page). '' without a phone.
 */
export function shippedText(o, site = 'https://www.soralifestyle.in') {
  const first = String(o?.customer?.firstName || '').trim().split(' ')[0];
  const carrier = String(o?.carrier_name || '').trim();
  const track = /^https?:\/\//i.test(String(o?.tracking_url || '')) ? o.tracking_url : `${site}/account/orders`;
  const awb = String(o?.tracking_number || '').trim();
  return `Hi${first ? ` ${first}` : ''}, this is SORA LIFESTYLE. Your order ${o?.order_number || ''} is on its way${carrier ? ` with ${carrier}` : ''}.${awb ? ` Tracking number: ${awb}.` : ''} Track it here: ${track}`;
}
export function shippedHref(o) {
  const d = String(o?.customer?.phone || '').replace(/\D/g, '');
  const n = d.length === 10 ? `91${d}` : d.length === 12 && d.startsWith('91') ? d : '';
  return n ? `https://wa.me/${n}?text=${encodeURIComponent(shippedText(o))}` : '';
}

// The audit trail an order can prove from its own columns. Steps with no
// timestamp are not shown — nothing here is inferred or back-dated.
function timeline(o) {
  const steps = [
    ['Order placed', o.created_at],
    ['Payment received', o.paid_at],
    ['Invoice generated', o.invoiced_at],
    ['Shipped', o.shipped_at],
    ['Delivered', o.delivered_at],
    ['Cancelled', o.cancelled_at],
  ];
  return steps.filter(([, at]) => Boolean(at)).map(([label, at]) => [label, dt(at)]);
}

// One row of the money breakdown. Rendered only when the order genuinely
// carries the figure, so a zero is never mistaken for a real charge.
function Money({ label, value, tone, strong }) {
  return (
    <div className={`adm-bill__row${tone ? ` is-${tone}` : ''}${strong ? ' is-strong' : ''}`}>
      <span>{label}</span><span>{value}</span>
    </div>
  );
}

export default function Orders() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState('');
  const [expandedId, setExpandedId] = useState(null);
  const [copiedId, setCopiedId] = useState(null);
  // Recorded admin actions per order (0040) — who collected a COD order's
  // cash — loaded when its details open.
  const [events, setEvents] = useState({});
  // The order whose packing slip is being printed (round 22).
  const [slipOrder, setSlipOrder] = useState(null);
  function printSlip(order) {
    setSlipOrder(order);
    document.body.classList.add('adm-printing-slip');
    const done = () => { document.body.classList.remove('adm-printing-slip'); window.removeEventListener('afterprint', done); };
    window.addEventListener('afterprint', done);
    setTimeout(() => { window.print(); }, 60);
  }

  async function loadEvents(orderId) {
    try {
      const list = await adminListOrderEvents(orderId);
      setEvents((current) => ({ ...current, [orderId]: list }));
    } catch { /* the details still show without the record */ }
  }

  function toggleDetails(order) {
    const opening = expandedId !== order.id;
    setExpandedId(opening ? order.id : null);
    if (opening) loadEvents(order.id);
  }

  useEffect(() => {
    adminListOrders()
      .then(setOrders)
      .catch((e) => setErr(e.message || String(e)))
      .finally(() => setLoading(false));
  }, []);

  const paidCount = orders.filter((o) => o.payment_status === 'paid').length;
  const [exporting, setExporting] = useState(false);
  async function exportCsv() {
    setExporting(true);
    try {
      const all = await adminListOrders(5000);
      downloadCsv(`sora-orders-${new Date().toISOString().slice(0, 10)}.csv`, ordersCsv(all));
    } catch (e) { setErr(e.message || String(e)); } finally { setExporting(false); }
  }

  async function copyAddress(order) {
    const text = formatAddress(order.customer);
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      // Clipboard API can be unavailable (insecure context) — fall back.
      const ta = document.createElement('textarea');
      ta.value = text; document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); } catch { /* ignore */ }
      document.body.removeChild(ta);
    }
    setCopiedId(order.id);
    setTimeout(() => setCopiedId((c) => (c === order.id ? null : c)), 1600);
  }

  function updateOrder(patch) {
    setOrders((current) => current.map((order) => (order.id === patch.id ? { ...order, ...patch } : order)));
    // Cash just recorded as collected: show who, from the record itself.
    if (patch.payment_status === 'paid') loadEvents(patch.id);
  }

  return (
    <div>
      <div className="adm__head">
        <div>
          <h1>Orders</h1>
          <p>{loading ? 'Loading…' : `${orders.length} orders · ${paidCount} paid`}</p>
        </div>
        {orders.length > 0 && (
          <button type="button" className="btn btn-sm btn-ghost" onClick={exportCsv} disabled={exporting} title="Every order as a spreadsheet (no street, phone or email)">
            {exporting ? 'Preparing…' : 'Download CSV'}
          </button>
        )}
      </div>

      {err && (
        <div className="adm-banner err">
          {err}
          <div style={{ marginTop: 8, fontSize: 12 }}>
            If the orders table does not exist yet, run
            <code> supabase/migrations/0003_orders.sql </code> in the Supabase SQL editor.
          </div>
        </div>
      )}

      {loading ? (
        <p className="muted">Loading orders…</p>
      ) : orders.length === 0 ? (
        <div className="adm-empty">No orders yet. Orders appear here once a customer completes checkout.</div>
      ) : (
        <div className="adm-table-wrap">
          <table className="adm-table">
            <thead>
              <tr>
                <th>Order</th><th>Placed</th><th>Customer</th><th>Amount</th><th>Method</th><th>Payment</th><th>Fulfillment</th><th></th>
              </tr>
            </thead>
            <tbody>
              {orders.map((o) => {
                const c = o.customer || {};
                const name = [c.firstName, c.lastName].filter(Boolean).join(' ') || '—';
                const open = expandedId === o.id;
                const b = o.billing && typeof o.billing === 'object' ? o.billing : null;
                const tax = b?.tax || null;
                return (
                  <Fragment key={o.id}>
                    <tr className={open ? 'adm-order-row--open' : ''}>
                      <td>
                        <strong>{o.order_number}</strong>
                        {o.razorpay_payment_id && <span className="hint" style={{ display: 'block' }}>{o.razorpay_payment_id}</span>}
                      </td>
                      <td>{new Date(o.created_at).toLocaleString('en-IN')}</td>
                      <td>
                        {name}
                        {c.email && <span className="hint" style={{ display: 'block' }}>{c.email}</span>}
                      </td>
                      <td><strong>{money((o.amount_paise || 0) / 100)}</strong></td>
                      <td>{o.payment_method === 'cod' ? 'Cash on delivery' : 'Razorpay'}</td>
                      <td>
                        <span className={`badge ${STATUS_BADGE[o.payment_status] || 'badge-soft'}`}>
                          {o.payment_status}
                        </span>
                        {holdWarnings(o).length > 0 && <span className="badge badge-sale" style={{ marginLeft: 6 }}>Check stock</span>}
                      </td>
                      <td>
                        <span className={`badge ${FULFILLMENT_BADGE[o.fulfillment_status] || 'badge-soft'}`}>
                          {fulfillmentStatusLabel(o.fulfillment_status) || 'Not set'}
                        </span>
                      </td>
                      <td>
                        <button className="btn btn-sm btn-light" onClick={() => toggleDetails(o)}>
                          {open ? 'Hide' : 'View details'}
                        </button>
                      </td>
                    </tr>

                    {open && (
                      <tr className="adm-order-detail">
                        <td colSpan={8}>
                          {holdWarnings(o).length > 0 && (
                            <div className="adm-banner err" role="alert">
                              <strong>Paid, but not everything could be honoured.</strong> Restock or refund before shipping.
                              <ul style={{ margin: '8px 0 0', paddingLeft: 18 }}>
                                {holdWarnings(o).map((w, i) => <li key={i}>{holdWarningText(w)}</li>)}
                              </ul>
                            </div>
                          )}
                          <div className="adm-order-detail__grid">
                            {/* Delivery / shipping */}
                            <section className="adm-order-block">
                              <div className="adm-order-block__head">
                                <h3>Delivery address</h3>
                                {hasAddress(c) && (
                                  <button className="btn btn-sm btn-light" onClick={() => copyAddress(o)}>
                                    {copiedId === o.id ? 'Copied ✓' : 'Copy address'}
                                  </button>
                                )}
                              </div>
                              {hasAddress(c) ? (
                                <address className="adm-address">{formatAddress(c)}</address>
                              ) : (
                                <p className="muted">No delivery address was recorded for this order.</p>
                              )}
                            </section>

                            {/* Contact */}
                            <section className="adm-order-block">
                              <h3>Contact</h3>
                              <dl className="adm-kv">
                                <div><dt>Name</dt><dd>{name}</dd></div>
                                <div><dt>Phone</dt><dd>{c.phone || '—'}</dd></div>
                                <div><dt>Email</dt><dd>{c.email || '—'}</dd></div>
                              </dl>
                              {/* Ask for a review (round 21, 2026-11-20): delivered orders, on WhatsApp, the admin presses send. */}
                              {o.fulfillment_status === 'delivered' && reviewAskHref(o) && (
                                <a className="btn btn-sm btn-outline" style={{ marginTop: 10 }} href={reviewAskHref(o)} target="_blank" rel="noopener noreferrer">Ask for a review on WhatsApp</a>
                              )}
                              {/* Tell them it shipped (round 22): the tracking link, on WhatsApp, the admin presses send. */}
                              {o.fulfillment_status === 'shipped' && shippedHref(o) && (
                                <a className="btn btn-sm btn-outline" style={{ marginTop: 10 }} href={shippedHref(o)} target="_blank" rel="noopener noreferrer">Send "shipped" on WhatsApp</a>
                              )}
                            </section>

                            {/* Order + payment meta */}
                            <section className="adm-order-block">
                              <h3>Order &amp; payment</h3>
                              <dl className="adm-kv">
                                <div><dt>Order ID</dt><dd>{o.order_number}</dd></div>
                                {o.invoice_number && <div><dt>Invoice no.</dt><dd>{o.invoice_number}</dd></div>}
                                <div><dt>Placed</dt><dd>{dt(o.created_at)}</dd></div>
                                <div><dt>Method</dt><dd>{o.payment_method === 'cod' ? 'Cash on delivery' : 'Razorpay'}</dd></div>
                                <div>
                                  <dt>Payment</dt>
                                  <dd><span className={`badge ${STATUS_BADGE[o.payment_status] || 'badge-soft'}`}>{o.payment_status}</span></dd>
                                </div>
                                <div><dt>Delivery</dt><dd>{o.delivery_method || '—'}</dd></div>
                                {/* Transaction ids exist only for a real gateway payment. COD
                                    and unpaid orders show nothing rather than a stand-in. */}
                                {o.razorpay_payment_id && (
                                  <div><dt>Transaction ID</dt><dd className="adm-mono">{o.razorpay_payment_id}</dd></div>
                                )}
                                {o.razorpay_order_id && (
                                  <div><dt>Gateway order</dt><dd className="adm-mono">{o.razorpay_order_id}</dd></div>
                                )}
                                {o.failure_reason && <div><dt>Failure</dt><dd>{o.failure_reason}</dd></div>}
                                {(events[o.id] || []).filter((e) => e.action === 'cod_collected').map((e) => (
                                  <div key={e.created_at}><dt>Cash collected by</dt><dd>{e.admin_email || 'an admin (no email on record)'} · {dt(e.created_at)}</dd></div>
                                ))}
                              </dl>
                              <CashCollected order={o} onUpdated={updateOrder} />
                              <Link to={`/invoice/${o.order_number}`} className="btn btn-sm" style={{ marginTop: 10 }}>
                                Open invoice
                              </Link>
                              <button type="button" className="btn btn-sm btn-light" style={{ marginTop: 10, marginLeft: 8 }} onClick={() => printSlip(o)}>
                                Print packing slip
                              </button>
                            </section>

                            <FulfillmentEditor order={o} onUpdated={updateOrder} />

                            {/* Timeline */}
                            {timeline(o).length > 0 && (
                              <section className="adm-order-block">
                                <h3>Timeline</h3>
                                <ol className="adm-timeline">
                                  {timeline(o).map(([label, when]) => (
                                    <li key={label}>
                                      <span className="adm-timeline__label">{label}</span>
                                      <span className="adm-timeline__at">{when}</span>
                                    </li>
                                  ))}
                                </ol>
                              </section>
                            )}

                            {/* Items */}
                            <section className="adm-order-block adm-order-block--wide">
                              <h3>Items</h3>
                              {Array.isArray(o.items) && o.items.length ? (
                                <table className="adm-items">
                                  <thead>
                                    <tr>
                                      <th>Product</th><th>Variant</th>
                                      <th className="adm-items__amt">MRP</th>
                                      <th className="adm-items__amt">Price</th>
                                      <th className="adm-items__qty">Qty</th>
                                      <th className="adm-items__amt">Amount</th>
                                    </tr>
                                  </thead>
                                  <tbody>
                                    {o.items.map((it, i) => {
                                      const unit = Number(it.unit_price) || 0;
                                      const mrp = Number(it.unit_mrp) || 0;
                                      return (
                                        <tr key={i}>
                                          <td>
                                            {it.name || it.product_id}
                                            {it.sku && <span className="hint" style={{ display: 'block' }}>{it.sku}</span>}
                                          </td>
                                          <td>{it.variant || '—'}</td>
                                          <td className="adm-items__amt">{mrp > unit ? <s>{money(mrp)}</s> : '—'}</td>
                                          <td className="adm-items__amt adm-price">{money(unit)}</td>
                                          <td className="adm-items__qty">× {it.qty}</td>
                                          <td className="adm-items__amt">{money(Number(it.line_total ?? unit * it.qty) || 0)}</td>
                                        </tr>
                                      );
                                    })}
                                  </tbody>
                                </table>
                              ) : (
                                <p className="muted">No item detail stored for this order.</p>
                              )}
                            </section>

                            {/* Money breakdown — straight from the server-computed billing
                                snapshot stored at checkout. Nothing is recalculated here. */}
                            <section className="adm-order-block adm-order-block--wide">
                              <h3>Billing breakdown</h3>
                              <div className="adm-bill">
                                {b ? (
                                  <>
                                    {b.mrpTotal > b.itemTotal && <Money label="MRP total" value={money(b.mrpTotal)} tone="mrp" />}
                                    <Money label="Item total" value={money(b.itemTotal)} />
                                    {b.productDiscount > 0 && (
                                      <Money label="Product discount" value={`-${money(b.productDiscount)}`} tone="save" />
                                    )}
                                    {b.couponDiscount > 0 && (
                                      <Money
                                        label={`Coupon discount${b.coupon?.code ? ` (${b.coupon.code})` : ''}`}
                                        value={`-${money(b.couponDiscount)}`}
                                        tone="save"
                                      />
                                    )}
                                    <Money label="Subtotal" value={money(b.subtotal)} />
                                    <Money label="Shipping" value={b.shipping > 0 ? money(b.shipping) : 'FREE'} />
                                    {b.platformFee > 0 && <Money label="Platform fee" value={money(b.platformFee)} />}
                                    {b.packagingFee > 0 && <Money label="Packaging fee" value={money(b.packagingFee)} />}
                                    {tax && (
                                      <>
                                        <Money label="Taxable amount" value={money(tax.taxableAmount)} />
                                        {tax.kind === 'cgst_sgst' ? (
                                          <>
                                            <Money label="CGST" value={money(tax.cgst)} />
                                            <Money label="SGST" value={money(tax.sgst)} />
                                          </>
                                        ) : tax.kind === 'igst' ? (
                                          <Money label="IGST" value={money(tax.igst)} />
                                        ) : (
                                          <Money label="GST" value={money(tax.totalTax)} />
                                        )}
                                      </>
                                    )}
                                  </>
                                ) : (
                                  <p className="muted">
                                    This order predates the stored billing breakdown. Only the charged total is on record.
                                  </p>
                                )}
                                <Money label="Grand total" value={money((o.amount_paise || 0) / 100)} strong />
                                {tax?.mode === 'inclusive' && <p className="hint">Inclusive of all taxes.</p>}
                              </div>
                            </section>
                          </div>
                        </td>
                      </tr>
                    )}
                  </Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
      {slipOrder && <PackingSlip order={slipOrder} />}
    </div>
  );
}

// A cash-on-delivery order is unpaid until the cash is collected. This records
// that moment: the order becomes paid and gets its invoice number (the server
// route checks the admin and writes once, so a second click changes nothing).
// Shown only for an unpaid COD order that is not cancelled.
function CashCollected({ order, onUpdated }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  if (order.payment_method !== 'cod' || order.payment_status === 'paid' || order.fulfillment_status === 'cancelled') return null;

  async function record() {
    if (busy) return;
    // eslint-disable-next-line no-alert
    if (!window.confirm(`Record that the cash for order ${order.order_number} has been collected? It will be marked paid and issued its invoice number.`)) return;
    setBusy(true); setError('');
    try {
      onUpdated(await adminMarkCodCollected(order.order_number));
    } catch (err) {
      setError(err?.message || 'The payment could not be recorded.');
    } finally {
      setBusy(false);
    }
  }

  return (
    <div style={{ marginTop: 10 }}>
      <button type="button" className="btn btn-sm btn-light" disabled={busy} onClick={record}>
        {busy ? 'Recording…' : 'Mark cash collected'}
      </button>
      {error && <p className="error-text" role="alert">{error}</p>}
    </div>
  );
}

function FulfillmentEditor({ order, onUpdated }) {
  const [form, setForm] = useState(() => ({
    fulfillmentStatus: order.fulfillment_status || '',
    carrierName: order.carrier_name || '',
    trackingNumber: order.tracking_number || '',
    trackingUrl: order.tracking_url || '',
  }));
  const [busy, setBusy] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    setForm({
      fulfillmentStatus: order.fulfillment_status || '',
      carrierName: order.carrier_name || '',
      trackingNumber: order.tracking_number || '',
      trackingUrl: order.tracking_url || '',
    });
  }, [order.id, order.fulfillment_status, order.carrier_name, order.tracking_number, order.tracking_url]);

  const field = (key) => (event) => setForm((current) => ({ ...current, [key]: event.target.value }));

  async function save(action = 'save') {
    if (busy) return;
    setBusy(action); setMessage(''); setError('');
    try {
      const safe = validateFulfillmentInput(form);
      const updated = await adminUpdateOrderFulfillment(order.id, safe, {
        markShipped: action === 'shipped',
        markDelivered: action === 'delivered',
      });
      onUpdated(updated);
      setMessage(action === 'save' ? 'Fulfillment details saved.' : action === 'shipped' ? 'Order marked shipped.' : 'Order marked delivered.');
    } catch (err) {
      setError(err?.message || 'Fulfillment details could not be saved.');
    } finally {
      setBusy('');
    }
  }

  return (
    <section className="adm-order-block adm-order-block--wide adm-fulfillment">
      <h3>Fulfillment &amp; tracking</h3>
      <p className="hint">Enter only details supplied by the carrier. A customer tracking link appears only for an explicit public HTTPS URL.</p>
      <div className="adm-grid2 adm-fulfillment__fields">
        <div className="field">
          <label className="label" htmlFor={`fulfillment-status-${order.id}`}>Fulfillment status</label>
          <select id={`fulfillment-status-${order.id}`} className="select" value={form.fulfillmentStatus} onChange={field('fulfillmentStatus')}>
            <option value="">Not set</option>
            {FULFILLMENT_STATUSES.map((status) => <option key={status} value={status}>{fulfillmentStatusLabel(status)}</option>)}
          </select>
        </div>
        <div className="field">
          <label className="label" htmlFor={`carrier-${order.id}`}>Carrier</label>
          <input id={`carrier-${order.id}`} className="input" maxLength={120} value={form.carrierName} onChange={field('carrierName')} placeholder="Carrier name" />
        </div>
        <div className="field">
          <label className="label" htmlFor={`tracking-number-${order.id}`}>Tracking number</label>
          <input id={`tracking-number-${order.id}`} className="input" maxLength={160} value={form.trackingNumber} onChange={field('trackingNumber')} placeholder="Carrier-issued number" />
        </div>
        <div className="field">
          <label className="label" htmlFor={`tracking-url-${order.id}`}>Tracking URL</label>
          <input id={`tracking-url-${order.id}`} className="input" type="url" inputMode="url" maxLength={2048} value={form.trackingUrl} onChange={field('trackingUrl')} placeholder="https://carrier.example/track/…" />
        </div>
      </div>
      {error && <p className="error-text" role="alert">{error}</p>}
      {message && <p className="adm-fulfillment__success" role="status">{message}</p>}
      <div className="adm-fulfillment__actions">
        <button type="button" className="btn btn-sm" disabled={Boolean(busy)} onClick={() => save('save')}>{busy === 'save' ? 'Saving…' : 'Save details'}</button>
        <button type="button" className="btn btn-sm btn-light" disabled={Boolean(busy)} onClick={() => save('shipped')}>{busy === 'shipped' ? 'Saving…' : 'Mark shipped'}</button>
        <button type="button" className="btn btn-sm btn-light" disabled={Boolean(busy)} onClick={() => save('delivered')}>{busy === 'delivered' ? 'Saving…' : 'Mark delivered'}</button>
      </div>
    </section>
  );
}
